"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["86489"],{1524(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_valor_dominio.ordem_invalida","status":422,"titulo":"Ordem do valor de dom\xednio n\xe3o pode ser negativa"},"descricao":{"codigo":"uniplus.configuracao.fato_valor_dominio.ordem_invalida","requisitos":[],"oQueAconteceu":["O administrador acrescentou um valor a um fato do cat\xe1logo (`POST /api/configuracao/admin/fatos-candidato/{id}/valores`) com um n\xfamero de ordem negativo. A ordem \xe9 a posi\xe7\xe3o em que o valor aparece entre as op\xe7\xf5es do fato, e come\xe7a em zero.","A recusa vem na lista `errors` da resposta, com `field` igual a `ordem`. Se o corpo tiver outros problemas, cada um vem numa entrada pr\xf3pria da mesma resposta, e nada \xe9 gravado. A busca do fato vem antes da confer\xeancia do corpo: com um `{id}` que n\xe3o existe, a resposta \xe9 a de fato n\xe3o encontrado (`uniplus.configuracao.fato_candidato.nao_encontrado`), e n\xe3o esta."],"comoResolver":["Envie a ordem como zero ou um n\xfamero positivo. Para mudar a posi\xe7\xe3o dos valores depois de cadastrados, reordene o fato inteiro (`PUT /api/configuracao/admin/fatos-candidato/{id}/ordem-dos-valores`), com a lista completa dos c\xf3digos."],"ondeAparece":["Acr\xe9scimo de um valor a um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato valor dominio"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);